from pathlib import Path
import re

ROOT=Path(__file__).resolve().parents[2]
def read(p): return (ROOT/p).read_text(encoding='utf-8')
def write(p,s): (ROOT/p).write_text(s,encoding='utf-8')

# models
p='app/modules/equipment_types/models.py';s=read(p)
if 'class EquipmentModelSpecDefinition' not in s:
    s=s.replace('    brand = relationship("EquipmentBrand", back_populates="models")','    brand = relationship("EquipmentBrand", back_populates="models")\n    spec_values = relationship("EquipmentModelSpecValue", back_populates="model", cascade="all, delete-orphan")',1)
    s+='''\n\nclass EquipmentModelSpecDefinition(Base, TimestampMixin):\n    __tablename__ = "equipment_model_spec_definitions"\n    id = Column(Integer, primary_key=True, index=True)\n    name = Column(String(100), unique=True, nullable=False)\n    data_type = Column(String(20), nullable=False, default="text")\n    unit = Column(String(20), nullable=True)\n    options = Column(String(500), nullable=True)\n    sort_order = Column(Integer, nullable=False, default=0)\n    values = relationship("EquipmentModelSpecValue", back_populates="definition", cascade="all, delete-orphan")\n\nclass EquipmentModelSpecValue(Base, TimestampMixin):\n    __tablename__ = "equipment_model_spec_values"\n    __table_args__ = (UniqueConstraint("equipment_model_id", "spec_definition_id", name="uq_model_spec_value"),)\n    id = Column(Integer, primary_key=True, index=True)\n    equipment_model_id = Column(Integer, ForeignKey("equipment_models.id", ondelete="CASCADE"), nullable=False, index=True)\n    spec_definition_id = Column(Integer, ForeignKey("equipment_model_spec_definitions.id", ondelete="CASCADE"), nullable=False, index=True)\n    value = Column(String(255), nullable=False)\n    definition = relationship("EquipmentModelSpecDefinition", back_populates="values")\n    model = relationship("EquipmentModel", back_populates="spec_values")\n'''
    write(p,s)

# schemas
p='app/modules/equipment_types/schemas.py';s=read(p)
if 'class SpecDefinitionCreate' not in s:
    s=s.replace('MOBILITY_TYPES = {"mobile", "towed"}','MOBILITY_TYPES = {"mobile", "towed"}\nSPEC_DATA_TYPES = {"text", "number", "select"}',1)
    ins='''class SpecDefinitionCreate(BaseModel):\n    name: str\n    data_type: str = "text"\n    unit: Optional[str] = None\n    options: Optional[str] = None\n    @field_validator("data_type")\n    @classmethod\n    def data_type_valid(cls,v: str) -> str:\n        if v not in SPEC_DATA_TYPES: raise ValueError(f"نوع الخاصية يجب أن يكون أحد: {SPEC_DATA_TYPES}")\n        return v\n\nclass SpecDefinitionOut(BaseModel):\n    model_config = ConfigDict(from_attributes=True)\n    id: int\n    name: str\n    data_type: str\n    unit: Optional[str]\n    options: Optional[str]\n    sort_order: int\n\nclass SpecValueInput(BaseModel):\n    definition_id: int\n    value: str\n\n'''
    s=s.replace('class EquipmentModelCreate(BaseModel):',ins+'class EquipmentModelCreate(BaseModel):',1)
    s=s.replace('    sizes: list[str] = Field(default_factory=list)','    sizes: list[str] = Field(default_factory=list)\n    specs: list[SpecValueInput] = Field(default_factory=list)',1)
    write(p,s)

# services
p='app/modules/equipment_types/services.py';s=read(p)
if 'EquipmentModelSpecDefinition' not in s:
    s=s.replace('from app.modules.equipment_types.models import EquipmentBrand, EquipmentCategory, EquipmentModel, EquipmentType','from app.modules.equipment_types.models import EquipmentBrand, EquipmentCategory, EquipmentModel, EquipmentType, EquipmentModelSpecDefinition, EquipmentModelSpecValue',1)
    s=s.replace('from app.modules.equipment_types.schemas import EquipmentBrandCreate, EquipmentBrandUpdate, EquipmentCategoryCreate, EquipmentCategoryUpdate, EquipmentModelCreate, EquipmentTypeCreate, EquipmentTypeUpdate','from app.modules.equipment_types.schemas import EquipmentBrandCreate, EquipmentBrandUpdate, EquipmentCategoryCreate, EquipmentCategoryUpdate, EquipmentModelCreate, EquipmentTypeCreate, EquipmentTypeUpdate, SpecDefinitionCreate, SpecValueInput',1)
    s=s.replace('def list_models(db:Session,type_id:Optional[int]=None)->list[EquipmentModel]:','''def list_spec_definitions(db: Session) -> list[EquipmentModelSpecDefinition]:\n    return db.query(EquipmentModelSpecDefinition).order_by(EquipmentModelSpecDefinition.sort_order, EquipmentModelSpecDefinition.name).all()\n\ndef create_spec_definition(db: Session, data: SpecDefinitionCreate) -> EquipmentModelSpecDefinition:\n    name=data.name.strip()\n    if not name: raise ValueError("اسم الخاصية مطلوب")\n    if db.query(EquipmentModelSpecDefinition).filter(EquipmentModelSpecDefinition.name==name).first(): raise ValueError("توجد خاصية بهذا الاسم مسبقًا")\n    options=None\n    if data.data_type=="select":\n        vals=[o.strip() for o in (data.options or "").split(",") if o.strip()]\n        if len(vals)<2: raise ValueError("خاصية من نوع اختيار تحتاج قيمتين على الأقل مفصولتين بفاصلة")\n        options=",".join(vals)\n    obj=EquipmentModelSpecDefinition(name=name,data_type=data.data_type,unit=(data.unit or "").strip() or None,options=options,sort_order=db.query(EquipmentModelSpecDefinition).count())\n    db.add(obj);db.commit();db.refresh(obj);return obj\n\ndef delete_spec_definition(db: Session, definition_id: int) -> None:\n    obj=db.query(EquipmentModelSpecDefinition).filter(EquipmentModelSpecDefinition.id==definition_id).first()\n    if obj is not None: db.delete(obj);db.commit()\n\ndef list_models(db:Session,type_id:Optional[int]=None)->list[EquipmentModel]:''',1)
    s=s.replace('joinedload(EquipmentModel.brand),joinedload(EquipmentModel.equipment_type).joinedload(EquipmentType.category)','joinedload(EquipmentModel.brand),joinedload(EquipmentModel.spec_values).joinedload(EquipmentModelSpecValue.definition),joinedload(EquipmentModel.equipment_type).joinedload(EquipmentType.category)',2)
    spec='''def _validate_and_sync_specs(db: Session, equipment_model_id: int, specs: list[SpecValueInput]):\n    definitions={d.id:d for d in db.query(EquipmentModelSpecDefinition).all()}\n    seen=set();normalized=[]\n    for item in specs:\n        if item.definition_id not in definitions: raise ValueError("توجد خاصية في النموذج لم تعد معرّفة في النظام")\n        if item.definition_id in seen: raise ValueError("لا يمكن إدخال نفس الخاصية أكثر من مرة لنفس الطراز")\n        seen.add(item.definition_id);value=(item.value or "").strip()\n        if not value: continue\n        definition=definitions[item.definition_id]\n        if definition.data_type=="number":\n            try: float(value)\n            except ValueError as exc: raise ValueError(f"قيمة '{definition.name}' يجب أن تكون رقمًا") from exc\n        elif definition.data_type=="select":\n            allowed={o.strip() for o in (definition.options or "").split(",")}\n            if value not in allowed: raise ValueError(f"قيمة '{definition.name}' يجب أن تكون إحدى: {definition.options}")\n        normalized.append((item.definition_id,value))\n    existing={r.spec_definition_id:r for r in db.query(EquipmentModelSpecValue).filter(EquipmentModelSpecValue.equipment_model_id==equipment_model_id).all()}\n    submitted={i for i,_ in normalized}\n    for did,row in existing.items():\n        if did not in submitted: db.delete(row)\n    for did,value in normalized:\n        if did in existing: existing[did].value=value\n        else: db.add(EquipmentModelSpecValue(equipment_model_id=equipment_model_id,spec_definition_id=did,value=value))\n\n'''
    s=s.replace('POSITION_SIDES={"left","right"};POSITION_TYPES={"single","inner","outer"}',spec+'POSITION_SIDES={"left","right"};POSITION_TYPES={"single","inner","outer"}',1)
    m=re.search(r'(def _validate_tire_positions_and_sizes\(.*?)(?=\ndef )',s,re.S)
    if m:
        b=m.group(1)
        if 'data.axle_count is not None:' not in b:
            hit='if len(keys)!=len(data.positions): raise ValueError("توجد مواضع إطارات مكررة")'
            if hit in b: b=b.replace(hit,hit+'\n        if data.axle_count is not None:\n            invalid=[p.axle_number for p in data.positions if p.axle_number>data.axle_count]\n            if invalid: raise ValueError(f"رقم المحور {max(invalid)} يتجاوز عدد محاور الطراز المحدد ({data.axle_count})")',1)
            s=s[:m.start(1)]+b+s[m.end(1):]
    def add_sync(fn,text):
        m=re.search(rf'(def {fn}\(.*?)(?=\ndef |\Z)',text,re.S)
        if not m or '_validate_and_sync_specs' in m.group(1): return text
        b=m.group(1);i=b.rfind('db.commit()')
        if i<0: raise SystemExit(f'commit anchor missing in {fn}')
        b=b[:i]+'db.flush();_validate_and_sync_specs(db,obj.id,data.specs)\n    '+b[i:]
        return text[:m.start(1)]+b+text[m.end(1):]
    s=add_sync('create_model',s);s=add_sync('update_model',s);write(p,s)

